alter policy "coordination reads maintenance activities" on public.operational_wall_posts using (audience_area='maintenance' and jsonb_array_length(coalesce(data->'actions','[]'::jsonb))>0 and exists(select 1 from public.device_identities d join public.authorized_users u using(employee_number) where d.auth_user_id=(select auth.uid()) and u.active and u.job_role='coordination' and (d.assigned_base is null or operational_wall_posts.base='Todas' or operational_wall_posts.base=d.assigned_base)));
